//! Short positions — what you can take, what it costs to carry, and the price that ends it.
//!
//! Three numbers decide whether a short works, and the one people compute is the least important.
//!
//! 1. **The margin call price.** A short is not a bet that ends when you are proved right or wrong;
//!    it ends when the broker says so. At the Regulation T maximum, a **15.4% rise closes the
//!    position** — you are out whether or not the thesis was correct. This module leads with that
//!    number because it is the one that actually determines the outcome.
//! 2. **The carry.** Borrow fees accrue daily and you owe every dividend the stock pays while you
//!    are short. A thesis that is right in eighteen months can lose to eighteen months of carry.
//! 3. **The profit**, which is the number everyone starts with and which is bounded above by 100%
//!    — the stock can only go to zero — while the loss has no bound at all.
//!
//! # Maximum loss on a naked short is ABSENT, not large
//!
//! There is no number, because the price has no ceiling. [`Exposure::max_loss`] is `None` for a
//! naked short and `Some` for a put, and that difference is the entire argument for the put. A
//! module that returned a big number here would be inviting somebody to plan around it.
use crate::money::{money, Currency, Money};

pub use capacity::capacity;
pub use outcome_at::outcome_at;
pub use ladder::ladder;
pub use compare::compare;
pub use put_payoff::put_payoff;
pub use put_breakeven::put_breakeven;
pub use inverse_drift::inverse_drift;

/// How the short is expressed. The vehicles differ in what can go wrong, which is the point.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Vehicle {
    /// Borrow the shares and sell them. Unlimited loss, margin required, borrow fees, and you owe
    /// the dividends.
    Naked,
    /// Buy a put. Loss is capped at the premium and there is no margin, no borrow and no dividend
    /// liability — you pay for all of that up front in the premium.
    Put,
    /// Buy an inverse fund. No margin, loss capped at what you put in — and it REBALANCES DAILY, so
    /// over more than a day or two it drifts away from the index return in a way that is not a fee
    /// and not a mistake, but is a real cost. See [`inverse_drift`].
    InverseEtf,
}

impl Vehicle {
    pub fn label(self) -> &'static str {
        match self {
            Vehicle::Naked => "naked short",
            Vehicle::Put => "put",
            Vehicle::InverseEtf => "inverse ETF",
        }
    }
}

pub struct MarginRules {
    /// Your own share of the position at entry. Regulation T is 0.50 — $5,000 of equity shorts
    /// $10,000 of stock.
    pub initial: f64,
    /// Equity that must be maintained against the position's CURRENT value. FINRA's floor is 0.25
    /// and brokers commonly require 0.30 or more, which is why the default here is the stricter one:
    /// a call price computed at the regulatory minimum is later than the one you will actually get.
    pub maintenance: f64,
}

impl Default for MarginRules {
    fn default() -> Self {
        MarginRules { initial: 0.50, maintenance: 0.30 }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct Capacity {
    pub equity: Money,
    pub price: Money,
    /// The largest position Regulation T allows against this equity.
    pub max_position: Money,
    pub max_shares: i64,
    /// The price at which a maintenance call arrives on a position of `shares`.
    pub margin_call_price: Money,
    /// How far the stock may rise first, as a fraction. THE number to look at.
    pub headroom: f64,
    pub notes: Vec<String>,
}

pub struct Carry {
    /// Annualised stock borrow rate. Hard-to-borrow names run well above 0.10 and can exceed 1.0.
    pub borrow_apr: f64,
    /// Dividends per share you expect to owe over the holding period. You pay these while short.
    pub dividends_per_share: Money,
    pub days_held: i64,
    /// Commission and fees, round trip, in total.
    pub commission: Money,
}

impl Carry {
    pub fn new(currency: Currency) -> Self {
        Carry { borrow_apr: 0.0, dividends_per_share: money(0, currency), days_held: 0, commission: money(0, currency) }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct Outcome {
    pub at_price: Money,
    /// Move in the underlying, as a fraction.
    pub move_pct: f64,
    /// Before any cost.
    pub gross: Money,
    pub borrow_cost: Money,
    pub dividends_owed: Money,
    pub commission: Money,
    pub net: Money,
    /// Net over the equity actually put up.
    pub return_on_equity: f64,
    /// FALSE when this price is at or beyond the margin call — the position ended before here, so
    /// the profit column is describing something that did not happen to you.
    pub reachable: bool,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Exposure {
    pub vehicle: Vehicle,
    /// What it costs to put on.
    pub capital_at_risk: Money,
    /// ABSENT for a naked short, because the price has no ceiling. This is the whole argument for
    /// the put, and it is represented as absence rather than as a large number.
    pub max_loss: Option<Money>,
    /// Bounded for every short: the stock can only reach zero.
    pub max_gain: Money,
    pub needs_margin: bool,
    pub note: &'static str,
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::money::usd;

    fn rules() -> MarginRules {
        MarginRules::default()
    }

    #[test]
    fn regulation_t_lets_you_short_twice_your_equity_and_no_more() {
        let c = capacity(usd(500_000), usd(10_000), None, &rules()).expect("computes");
        // $5,000 of equity shorts $10,000 of stock — the 50% is YOUR half; the other half is the
        // sale proceeds, which are not yours.
        assert_eq!(c.max_position.minor, 1_000_000);
        assert_eq!(c.max_shares, 100);
    }

    #[test]
    fn a_maxed_out_short_is_closed_by_a_fifteen_percent_rise() {
        // THE NUMBER NOBODY COMPUTES, and the one that decides the trade. Hand-checked:
        // (5000 + 100·100) / (100 · 1.30) = 115.3846
        let c = capacity(usd(500_000), usd(10_000), Some(100), &rules()).expect("computes");
        assert_eq!(c.margin_call_price.minor, 11_538, "115.3846 dollars, floored to the cent");
        assert!((c.headroom - 0.153846).abs() < 0.0001, "got {}", c.headroom);
        // A short is not a bet that ends when you are proved wrong. It ends when the broker says so,
        // and 15% is less than a bad week.
        assert!(c.headroom < 0.16);
    }

    #[test]
    fn a_smaller_position_buys_headroom_and_that_is_the_only_thing_that_does() {
        let full = capacity(usd(500_000), usd(10_000), Some(100), &rules()).expect("computes");
        let half = capacity(usd(500_000), usd(10_000), Some(50), &rules()).expect("computes");
        let quarter = capacity(usd(500_000), usd(10_000), Some(25), &rules()).expect("computes");
        assert!(half.headroom > full.headroom);
        assert!(quarter.headroom > half.headroom);
        // Halving the position more than doubles the survivable move — which is the argument for
        // sizing well under the maximum rather than at it.
        assert!(half.headroom > full.headroom * 2.0);
    }

    #[test]
    fn a_stricter_maintenance_requirement_brings_the_call_closer() {
        let finra_floor = capacity(usd(500_000), usd(10_000), Some(100), &MarginRules { initial: 0.50, maintenance: 0.25 }).expect("computes");
        let broker = capacity(usd(500_000), usd(10_000), Some(100), &rules()).expect("computes");
        // The default is the stricter 30% on purpose: a call price computed at FINRA's 25% floor is
        // LATER than the one your broker will actually give you.
        assert!(broker.margin_call_price.minor < finra_floor.margin_call_price.minor);
    }

    #[test]
    fn the_two_thousand_dollar_floor_is_stated_rather_than_assumed_away() {
        let small = capacity(usd(50_000), usd(1_000), None, &rules()).expect("computes");
        assert!(small.notes.iter().any(|n| n.contains("$2,000 of equity before it may short at all")));
        let fine = capacity(usd(500_000), usd(10_000), None, &rules()).expect("computes");
        assert!(!fine.notes.iter().any(|n| n.contains("$2,000")));
    }

    #[test]
    fn carry_is_charged_and_a_slow_thesis_pays_for_being_slow() {
        let c = capacity(usd(500_000), usd(10_000), Some(100), &rules()).expect("computes");
        // Right by 20%, but held a year at a 12% borrow with a dividend to cover.
        let carry = Carry { borrow_apr: 0.12, dividends_per_share: usd(200), days_held: 365, commission: usd(1_000) };
        let o = outcome_at(&c, 100, usd(8_000), &carry);
        assert_eq!(o.gross.minor, 200_000, "20 points on 100 shares");
        assert_eq!(o.borrow_cost.minor, 120_000, "12% of a 10000 position for a year");
        assert_eq!(o.dividends_owed.minor, 20_000, "$2 a share, and you owe it");
        assert_eq!(o.net.minor, 200_000 - 120_000 - 20_000 - 1_000);
        // Being right by twenty percent nets under a third of the gross once the carry is paid.
        assert!(o.net.minor * 3 < o.gross.minor * 2);
    }

    #[test]
    fn the_scenario_ladder_marks_the_rows_you_never_reach() {
        let c = capacity(usd(500_000), usd(10_000), Some(100), &rules()).expect("computes");
        let rows = ladder(&c, 100, &[-0.50, -0.25, -0.10, 0.0, 0.10, 0.25, 0.50], &Carry::new(Currency::USD));
        assert_eq!(rows.len(), 7);
        // Everything at or below +15% is live; +25% and +50% are past the call and the position
        // ended before them. The rows are KEPT so that is visible rather than filtered away.
        assert!(rows[0].reachable && rows[4].reachable);
        assert!(!rows[5].reachable, "+25% is past the call price");
        assert!(!rows[6].reachable, "+50% certainly is");
        // The profit column on an unreachable row is describing something that did not happen.
        assert!(rows[6].net.minor < 0);
    }

    #[test]
    fn the_maximum_loss_on_a_naked_short_is_absent_and_on_a_put_it_is_a_number() {
        let ex = compare(usd(10_000), 100, usd(500), usd(9_500), 1, usd(100_000));
        let naked = &ex[0];
        let put = &ex[1];
        // THE WHOLE ARGUMENT FOR THE PUT, expressed as the presence or absence of a number rather
        // than as a large one — a big figure here would invite somebody to size against it.
        assert!(naked.max_loss.is_none());
        assert_eq!(put.max_loss, Some(usd(50_000)), "the premium, and nothing more");
        assert!(naked.needs_margin && !put.needs_margin);
        // And the gain is bounded either way: the stock can only reach zero.
        assert_eq!(naked.max_gain.minor, 1_000_000);
    }

    #[test]
    fn a_put_breaks_even_below_the_strike_by_the_premium() {
        let (strike, premium) = (usd(9_500), usd(500));
        assert_eq!(put_breakeven(strike, premium).minor, 9_000);
        // At the breakeven it returns nothing; below it, it pays; above the strike the loss is the
        // premium and stops there however far the stock runs.
        assert_eq!(put_payoff(strike, premium, 1, usd(9_000)).minor, 0);
        assert_eq!(put_payoff(strike, premium, 1, usd(8_000)).minor, 100_000, "15 of intrinsic less the 5 premium, over 100 shares");
        assert_eq!(put_payoff(strike, premium, 1, usd(9_500)).minor, -50_000);
        assert_eq!(put_payoff(strike, premium, 1, usd(50_000)).minor, -50_000, "it stops at the premium");
    }

    #[test]
    fn a_daily_rebalanced_inverse_fund_loses_money_on_a_flat_index() {
        // Up 10%, then down 9.0909% — the index ends exactly where it began.
        let path = [0.10, -0.090909];
        let (expected, actual) = inverse_drift(&path, 3.0);
        assert!(expected.abs() < 0.0001, "the index is flat, so the label promises nothing: {expected}");
        // And the fund is down about 11%. That is not a fee and it is not an error — it is
        // compounding, and over a choppy year it is the dominant term.
        assert!((actual - -0.109091).abs() < 0.0001, "got {actual}");
        assert!(actual < -0.10);
    }

    #[test]
    fn over_a_single_day_the_inverse_fund_does_what_the_label_says() {
        let (expected, actual) = inverse_drift(&[0.02], 3.0);
        assert!((expected - actual).abs() < 1e-12, "one day is exactly -3x, which is the only horizon it promises");
        // Two days of a trend still track closely; it is CHOP that costs, not direction.
        let (e2, a2) = inverse_drift(&[-0.01, -0.01], 3.0);
        assert!(a2 > e2, "a sustained move compounds in your favour: {a2} vs {e2}");
    }

    #[test]
    fn inputs_that_cannot_support_a_position_are_refused() {
        assert!(capacity(usd(0), usd(10_000), None, &rules()).is_err());
        assert!(capacity(usd(500_000), usd(0), None, &rules()).is_err());
        assert!(capacity(usd(500_000), usd(10_000), None, &MarginRules { initial: 0.0, maintenance: 0.30 }).is_err());
        assert!(capacity(usd(500_000), usd(10_000), None, &MarginRules { initial: 0.5, maintenance: 1.5 }).is_err());
        // Equity too small for a single share is refused with the arithmetic that shows why.
        let e = capacity(usd(100), usd(10_000), None, &rules()).unwrap_err();
        assert!(e.contains("does not reach one share"));
        // A position larger than Regulation T allows still computes, and says it could not be opened.
        let over = capacity(usd(500_000), usd(10_000), Some(500), &rules()).expect("computes");
        assert!(over.notes.iter().any(|n| n.contains("could not open")));
    }
}
